from h import *
R(9849806,"كيكة الليمون والتوت الأزرق النباتية الصحية [خالية من الزيت]",
"قد تكون كيكة الليمون والتوت الأزرق النباتية هذه أكثر صحة من معظم الكيكات، لكنها رطبة وحلوة وشهية تمامًا.",
"10 حصص","حصة واحدة",
["¾ كوب حليب الصويا","¼ كوب عصير ليمون","1 ملعقة كبيرة قشر ليمون مبشور","¼ كوب صلصة التفاح غير المحلاة","1 ملعقة صغيرة مستخلص الفانيليا الطبيعي","270 غرام دقيق الشوفان (حوالي 3 أكواب بالملعقة مع تسوية السطح)","½ كوب سكر جوز الهند غير المكرر أو سكر بني","2 ملعقة صغيرة بيكنغ باودر","½ ملعقة صغيرة بيكربونات الصوديوم","1 كوب مكتنز من التوت الأزرق الطازج مقسّم"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (175° مئوية) وجهّز قالب كيك قطره تسع بوصات أو قالبًا دائريًا بمشبك. استخدم قالبًا غير لاصق، أو إذا لم يكن لديك قالب غير لاصق، فبطّنه بورق الزبدة، أو ادهنه بالدهن إذا كنت لا تتجنب الزيت.",
"اخلط حليب الصويا وعصير الليمون والقشر المبشور في وعاء صغير واتركه جانبًا لمدة 5 دقائق على الأقل حتى يبدأ بالثخانة والتخثر.",
"في الأثناء، ضع جميع المكونات الجافة في وعاء كبير واخفقها حتى تمتزج.",
"ثم أضف الحليب المتخثر مع بقية المكونات السائلة إلى الوعاء نفسه الذي فيه المكونات الجافة. امزج حتى لا تبقى كتل دقيق. ثم أضف ¾ كوب من التوت الأزرق بطيّه برفق.",
"اسكب العجينة في قالب الكيك وانثر التوت الأزرق المتبقي فوقها واضغط عليه برفق في الكيكة، قليلًا فقط.",
"اخبزها لمدة 25-30 دقيقة، أو حتى تخرج عود الأسنان نظيفة عند غرسها في الوسط. أخرجها من الفرن واتركها ترتاح 30 دقيقة أو أكثر قبل لمسها."],
["زِن الدقيق للحصول على أدق النتائج. إن لم يكن لديك ميزان مطبخ، يمكنك وضع الدقيق بالملعقة في كوب القياس وإزالة الزائد بسكين. لا تغرف من الكيس مباشرة! لا تتجاهل تحضير اللبن الرائب النباتي. (أي خلط حليب الصويا مع عصير الليمون.) فهذا يعزز نكهة الألبان ويجعل القوام أكثر هشاشة. تأكد من أن البيكنغ باودر وبيكربونات الصوديوم فعّالان. فالمنتجات المفتوحة التي تبقى في مخزنك لأكثر من 6 أشهر تبدأ بفقدان فعاليتها وقدرتها على الرفع. احفظ الكيك المتبقي في درجة حرارة الغرفة في وعاء محكم الإغلاق أو ملفوفًا بإحكام لمدة يومين. وفي الثلاجة لمدة تصل إلى 5 أيام أو جمّده في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر."],
{"Wet Ingredients":"المكونات السائلة","Dry Ingredients":"المكونات الجافة","For Fill in":"للحشو"})
R(9853178,"كوكيز براوني بالنعناع الفلفلي السهل [خالٍ من الزيت]",
"لكل محبي الشوكولاتة بالنعناع، هذه من أجلكم! كوكيز البراوني بالنعناع الفلفلي، أو ما يُعرف بالبروكيز النباتية، هي الحلوى الفاخرة المثالية! غنية بنكهة المكسرات والشوكولاتة ومترفة.",
"8 قطع كوكيز","قطعة كوكيز واحدة",
["½ كوب زبدة فول سوداني ناعمة أو مقرمشة، استخدم زبدة فول سوداني طبيعية مصنوعة من الفول السوداني فقط","¼ كوب شراب القيقب","⅓ كوب صلصة التفاح غير المحلاة","1 ملعقة صغيرة مستخلص النعناع الفلفلي","30 غرام مسحوق كاكاو خام غير محلى (حوالي ⅓ كوب)","25 غرام دقيق الشوفان (حوالي ¼ كوب)","1 ملعقة صغيرة بيكنغ باودر","عصي حلوى القصب (كاندي كين) مكسّرة"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175° مئوية) وبطّن صينية خبز بورق الزبدة.",
"ضع زبدة الفول السوداني وشراب القيقب وصلصة التفاح ومستخلص النعناع الفلفلي في وعاء وامزج جيدًا. ثم أضف جميع المكونات الجافة: مسحوق الكاكاو والدقيق والبيكنغ باودر وامزج حتى تمتزج. ستكون العجينة سميكة ولزجة.",
"قسّم الخليط إلى 8 أجزاء واستخدم يدين رطبتين لتشكيل كرات بقطر 1.5 بوصة تقريبًا. ضعها على صينية الخبز، وبلّل يديك مجددًا عند الحاجة لمنع التصاق العجينة بأصابعك. استخدم أطراف أصابعك للضغط برفق على كل قطعة لمنحها بداية انتشار.",
"اخبزها لمدة 11 دقيقة، ثم أخرجها من الفرن واتركها ترتاح لمدة 10 دقائق قبل لمسها. ثم اضغط قطع عصي حلوى القصب برفق فوق كل قطعة كوكيز، إن استخدمتها."],
["استخدم زبدة فول سوداني طبيعية. أي النوع المصنوع من الفول السوداني فقط، دون سكر أو ملح أو زيت مضاف. أو يمكنك تحضير زبدة فول سوداني منزلية. استخدم يدين مبللتين للتعامل مع عجينة الكوكيز. بعد خلط كل شيء، قسّم العجينة إلى 8 قطع كوكيز وشكّلها كرات بيدين مبللتين قليلًا. فهذا يمنع العجينة اللزجة من الالتصاق بأصابعك. لا تفرط في خبز البروكيز النباتية! فستبدو غير ناضجة وتُحَسّ كذلك عند الدقيقة 11، لكن أخرجها من الفرن على أي حال. اترك كوكيز البراوني بالنعناع الفلفلي ترتاح قبل لمسها. أخرج الصينية من الفرن ولا تلمسها لمدة 10 دقائق. فهذا يساعد الكوكيز على التماسك والثبات. وبعد فترة الراحة البالغة 10 دقائق، يمكنك تزيينها بعصي حلوى القصب المكسرة، إن استخدمتها. تُحفظ الكوكيز في درجة حرارة الغرفة لمدة 2-3 أيام، وفي الثلاجة لمدة تصل إلى أسبوع، أو مجمدة لمدة تصل إلى شهرين."],
{"Optional Garnish":"زينة اختيارية"})
R(9854744,"حمص مغطى بالشوكولاتة",
"لمسة خالية من المكسرات على اللوز المغطى بالشوكولاتة تقدم لك عناقيد الحمص المغطى بالشوكولاتة اللذيذة بشكل لا يُصدَّق!",
"16 عنقودًا","حصة واحدة",
["1.5 كوب حمص مطبوخ أو معلب (حوالي علبة 15 أونصة)","1 كوب رقائق الشوكولاتة النباتية","⅛ ملعقة صغيرة ملح البحر (اختياري)","ملح خشن للرش (اختياري)"],
["سخّن الفرن مسبقًا على 425° فهرنهايت (220° مئوية) بوضع الخبز بالحمل الحراري وبطّن صينية خبز بورق الزبدة.",
"رتّب الحمص في طبقة واحدة على الصينية واخبزه لمدة 15 دقيقة، ثم رجّه أو قلّبه واخبزه 10-15 دقيقة أخرى حتى يصبح مقرمشًا.",
"في آخر 5-10 دقائق من خبز الحمص، ذوّب الشوكولاتة في حمام مائي (بوان ماري). (إذا لم يكن لديك واحد، فاستخدم هذه الطريقة.)",
"ثم أضف ⅛ ملعقة صغيرة من الملح إلى الشوكولاتة المذابة وحرّك، وأضف الحمص المحمص. حرّك لتتغلف الحبات بالتساوي.",
"استخدم مغرفة كوكيز صغيرة أو ملعقة كبيرة لوضع عناقيد الحمص بالشوكولاتة على صينية الخبز نفسها. (يجب أن تحصل على حوالي 16 عنقودًا.)",
"الآن رش العناقيد بالملح الخشن (إن استخدمته) بينما الشوكولاتة لا تزال في حالتها الذائبة كي تلتصق الرقائق بالعناقيد. ثم ضع الصينية في الثلاجة لمدة ساعة واحدة على الأقل لتتصلب الشوكولاتة وتتماسك مجددًا قبل تناولها."],
[],
{})
R(9858921,"بولتين نباتي صحي تقريبًا",
"لمسة ممتعة على الطبق الكلاسيكي، هذا البولتين الصحي مغطى بصلصة «الجبن» والخضار الطازجة لوجبة مريحة بلا شعور بالذنب!",
"3 حصص","حصة واحدة",
["2 رطل بطاطس راسيت (حوالي 4-5 حبات متوسطة)","1 ملعقة كبيرة زيت الأفوكادو (احذفه واستخدم المرق للحصول على وصفة خالية من الزيت)","1 ملعقة صغيرة ملح البحر (استخدم ½ ملعقة صغيرة لتقليل الصوديوم)","1 حبة طماطم روما مقطعة إلى مكعبات","2-3 ملاعق كبيرة بصل أخضر مقطع إلى شرائح رفيعة","2-3 ملاعق كبيرة بصل أحمر مقطع إلى مكعبات","3 أكواب صلصة جبن نباتي (مرة واحدة من الوصفة المرتبطة)"],
["سخّن الفرن مسبقًا على 425 درجة فهرنهايت (220° مئوية) بوضع الشوي بالحمل الحراري. وإذا لم يكن لديك فرن بالحمل الحراري، فأضف بضع دقائق إلى وقت الطهي. بطّن صينية خبز كبيرة بورق الزبدة واتركها جانبًا.",
"قشّر البطاطس (إن رغبت) وقطّعها إلى أسافين بحجم بوصة واحدة. ضعها في وعاء خلط، ثم أضف الزيت (أو المرق) والملح وامزج جيدًا لتتغلف بالتساوي. ثم رتّب البطاطس في طبقة واحدة على صينية الخبز. اشوها على الرف السفلي من الفرن لمدة 25 دقيقة. ثم اقلب البطاطس وواصل الطهي 10-15 دقيقة أخرى، حتى تصبح البطاطس بنية ذهبية ومقرمشة.",
"بينما تنضج البطاطس، حضّر صلصة الجبن والإضافات.",
"ثم قدّم البطاطس في أطباق عميقة، وغطّها بصلصة الجبن وانثر فوقها إضافات الخضار. بالهناء والشفاء."],
["تأكد من أن البطاطس مقرمشة جدًا قبل إخراجها من الفرن كي تحافظ على شكلها ولا تصبح طرية بسبب الصلصة. للحصول على وصفة خالية من الزيت وأقل دهونًا، استخدم مرق الخضار لتقليب البطاطس بدلًا من الزيت. احرص على ترك مساحة إضافية قليلة بين قطع البطاطس كي لا تلتصق ببعضها وتتقرمش بشكل جيد. ولمزيد من النكهة، أضف قليلًا من مسحوق الثوم وإكليل الجبل المجروش وتوابل أخرى تحبها إلى أسافين البطاطس قبل الخبز. إذا كان لديك خلاط عالي السرعة، فستسخن صلصة الجبن بنفسها أثناء الخلط. وإن لم يكن لديك، فانقلها إلى قدر صغير بعد أن تصبح ناعمة لإبقائها دافئة على نار هادئة إلى متوسطة بينما تنتظر انتهاء خبز البطاطس. راقب القدر، فأنت تريد الصلصة دافئة وليست تغلي. اخفقها من حين لآخر. زيّن البولتين الصحي بكمية من كريمة الكاجو وإضافة «بيكون» البيكان. وإذا أردت بولتين تقليدي بمرق ساخن وقطع جبن، فاطلع على وصفة البولتين النباتي هذه بدلًا منه. المعلومات الغذائية لثلث الوصفة، وتشمل ثلثًا من صلصة الجبن الخالية من المكسرات الخاصة بي. وإذا استخدمت صلصة أخرى، فستختلف المعلومات."],
{"For the potato wedges":"لأسافين البطاطس","For topping the poutine":"لتغطية البولتين"})
R(9863153,"كيكة الشوكولاتة بالفاصولياء السوداء",
"كيكة الشوكولاتة بالفاصولياء السوداء الغنية والكثيفة هذه خالية من الغلوتين بشكل طبيعي وغنية بالبروتين.",
"8 حصص","حصة واحدة",
["علبة فاصولياء سوداء 400 مل مصفاة ومغسولة","½ كوب سكر جوز الهند غير المكرر","⅓ كوب صلصة التفاح غير المحلاة","200 غرام دقيق اللوز المقشّر (حوالي 2 كوب)","⅓ كوب مسحوق كاكاو غير محلى","3 ملاعق صغيرة بيكنغ باودر","¼ كوب رقائق الشوكولاتة (اختياري، للتزيين)"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (175° مئوية) وبطّن قالب رغيف بورق الزبدة.",
"ضع الفاصولياء والسكر وصلصة التفاح في وعاء محضّرة الطعام. اخلطها حتى تصبح ناعمة.",
"ثم أضف الدقيق ومسحوق الكاكاو والبيكنغ باودر واستمر في التشغيل حتى تمتزج. اكشط الجوانب عند الحاجة.",
"انقل عجينة الكيك إلى قالب الرغيف المبطن وانثر عليها رقائق الشوكولاتة إن استخدمتها. اخبزها في الفرن المسخّن مسبقًا لمدة 20-25 دقيقة، أو حتى تخرج عود الأسنان نظيفة في معظمها عند غرسها في الوسط.",
"أخرج الكيكة من الفرن واتركها تبرد لمدة 10-15 دقيقة قبل نقلها برفق إلى رف سلكي لتبرد تمامًا.",
"بعد أن تبرد، قطّع الكيكة إلى 8 أو 16 مربعًا مستخدمًا سكينًا مبللة بين كل قطعة وأخرى لمنع الالتصاق. (المعلومات الغذائية والصور تمثل 8 شرائح.)"],
["زِن الدقيق باستخدام ميزان المطبخ للحصول على أدق النتائج. فالغرف من الكيس قد يؤدي إلى استخدام كمية دقيق زائدة وقد يغيّر القوام.","استخدم بيكنغ باودر طازجًا وفعّالًا. فبعد فتحه يبدأ البيكنغ باودر بفقدان فعاليته، لذا من الأفضل استهلاكه خلال 6 أشهر.","اترك الكيكة تبرد في قالبها لمدة 10-15 دقيقة على الأقل قبل نقلها إلى رف التبريد لتبرد تمامًا.","استخدم سكينًا مبللة لتقطيع الكيكة للحصول على شرائح مرتبة ولمنع الالتصاق.","يُحفظ المتبقي في درجة حرارة الغرفة لمدة 1-2 يوم، وفي الثلاجة لمدة تصل إلى 5 أيام أو مجمدًا لمدة تصل إلى 3 أشهر."],
{})
R(9863545,"حساء الفطر والشعير [إنستانت بوت أو الموقد]",
"حساء الفطر والشعير اللذيذ ببساطة قليل الدهون لكنه غني بالنكهة. بـ 6 مكونات فقط، هذا الحساء الترابي الغني بنكهة الأومامي يستحق التجربة.",
"6 حصص","حصة واحدة",
["1 ملعقة كبيرة زبدة نباتية أو سمن نباتي (مارجرين) (تجاوزها للحصول على وصفة خالية من الزيت وقلّب في الماء أو المرق بدلًا منها)","2 حبة بصل أخضر صغير (إشالوت) مفرومة ناعمًا","3 فصوص ثوم مفرومة","1 رطل فطر كريميني مقطع إلى شرائح","1 كوب شعير غير مقشر (بوت) أو شعير مقشر","8 أكواب مرق خضار قليل الصوديوم","ملح وفلفل حسب الرغبة"],
["ذوّب الزبدة، إن استخدمتها، في قدر متوسط. ثم أضف الإشالوت والثوم وشرائح الفطر. قلّبها حتى تتقلص، حوالي 5-6 دقائق، ثم رش عليها الملح والفلفل.",
"أضف المرق والشعير واتركها حتى تغلي مع وضع الغطاء على القدر ولكن بشكل مائل قليلًا. اطبخها على نار متوسطة إلى عالية حتى يصبح الشعير طريًا، حوالي 40-45 دقيقة، مع التحريك من حين لآخر.",
"بعد النضج، أضف قليلًا من الملح والفلفل عند الحاجة، وقدّمه مزيّنًا بالبقدونس الطازج أو رقائق الفلفل الأحمر إن رغبت.",
"اضبط إنستانت بوت على وظيفة التقليب (السوتيه) وأضف الزبدة لتذوب، إن استخدمتها. أضف الإشالوت والثوم وشرائح الفطر ورش عليها الملح والفلفل. قلّبها حتى تتقلص، حوالي 5-6 دقائق.",
"أضف المرق والشعير وأغلق الغطاء. تأكد من ضبط الصمام على وضع الإغلاق واضبطه على الضغط العالي لمدة 22 دقيقة. سيستغرق حوالي 10-15 دقيقة لبناء الضغط وبدء العدّ التنازلي.",
"عند انتهاء المؤقت، حرّر البخار بسرعة من الصمام وافتح الغطاء عندما يكون ذلك آمنًا. تبّله بمزيد من الملح والفلفل عند الحاجة وقدّمه مزيّنًا بالبقدونس الطازج أو رقائق الفلفل الأحمر."],
["اطبخ الحساء مع وضع الغطاء ولكن بشكل مائل قليلًا. فالطهي دون غطاء سيؤدي إلى تبخر كمية كبيرة من المرق. الشعير يحتاج إلى وقت طويل للطهي، لذا سيبدو أن هناك الكثير من السائل في البداية، لكن الشعير سيمتص المزيد والمزيد منه أثناء الطهي. وللحصول على وصفة دون زيت، استخدم الماء أو المرق لتقليب الخضار. وإذا سمح الوقت، يمكنك إضافة المزيد من الخضار في خطوة التقليب. فالجزر والكرفس المفروم سيكونان إضافتين رائعتين. أو أضف بعض السبانخ الصغيرة (بيبي) في نهاية الطهي تمامًا، إن رغبت. يُحفظ المتبقي في الثلاجة لمدة 3-4 أيام، أو يمكنك تجميده في وعاء محكم الإغلاق مناسب للمجمّد لمدة تصل إلى 3 أشهر."],
{"Stove Top Instructions":"طريقة الموقد","Instant Pot Instructions":"طريقة إنستانت بوت"})
R(9864024,"فاهيتا الجاك فروت السريعة والسهلة",
"فاهيتا الجاك فروت هذه متبّلة بإتقان وغنية بالنكهة بشكل لا يُصدَّق، لعشاء سهل في أيام الأسبوع جاهز في 25 دقيقة.",
"4 حصص","حصة واحدة",
["1 ملعقة كبيرة زيت الأفوكادو (اختياري) *قلّب في المرق أو الماء للحصول على وصفة دون زيت","علبة جاك فروت أخضر صغير (غير ناضج) وزنها 20 أونصة في محلول ملحي أو ماء، وليس في شراب","1 بصلة حمراء مقطعة إلى شرائح","1 حبة فلفل رومي أحمر مقطعة إلى شرائح","1 حبة فلفل رومي أصفر مقطعة إلى شرائح","1 ملعقة كبيرة مسحوق الفلفل الحار (تشيلي)","1 ملعقة صغيرة كمون","1 ملعقة صغيرة بابريكا مدخنة","1 ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة أوريجانو مجفف","½ ملعقة صغيرة ملح البحر أو حسب الرغبة","¼ ملعقة صغيرة فلفل كايين أو حسب الرغبة","2 ملعقة صغيرة دخان سائل","2 ملعقة كبيرة عصير ليمون أخضر (حوالي حبة ليمون أخضر متوسطة)","خبز تورتيلا من القمح الكامل أو الذرة","كريما فريسكا نباتية","كزبرة خضراء طازجة","شرائح أفوكادو","جواكامولي"],
["صفِّ الجاك فروت واغسله جيدًا جدًا واستخدم يديك لتفتيت القطع ليشبه الدجاج المسحوب. استخدم جميع القطع، حتى أجزاء القلب الأقسى قليلًا، فلا داعي للتخلص من أي منها.",
"ضع الزيت (إن استخدمته) في مقلاة وعلى حرارة متوسطة إلى عالية، قلّب الجاك فروت حتى يتحمر قليلًا، حوالي 8-10 دقائق.",
"ثم أضف شرائح الخضار وكل التوابل وقلّبها 2-3 دقائق إضافية حتى يصبح الفلفل طريًا لكن مقرمشًا. لا تفرط في الطهي. ارفعها عن النار وقدّمها مع التورتيلا والإضافات التي تختارها."],
["احرص على استخدام جاك فروت أخضر صغير معلب في الماء أو المحلول الملحي. ولا تستبدله بجاك فروت طازج، أو جاك فروت مجفف معبأ ومتبّل، أو جاك فروت معلب في شراب. لا تفرط في طهي الخضار، فأنت تريدها طرية لكن مقرمشة للحصول على أفضل قوام. قدّم فاهيتا الجاك فروت دون تجميع ودع كل شخص يعدّ فاهيتاه بنفسه. فالتورتيلا ستصبح طرية جدًا إذا جُمّعت قبل وقت طويل. احفظ المتبقي في أوعية منفصلة (لا تحفظ الفاهيتا المجمّعة وإلا أصبحت طرية جدًا) في الثلاجة لمدة 3-4 أيام."],
{"Fajita Seasoning":"توابل الفاهيتا","Serve with (optional)":"للتقديم مع (اختياري)"})
R(9872571,"حساء القرنبيط والعدس",
"حساء القرنبيط والعدس النباتي هذا طبق مشبع ومغذٍّ ومليء بالنكهة.",
"6 حصص","حصة واحدة",
["1 بصلة صفراء كبيرة مقطعة إلى مكعبات","2 جزرة كبيرة مقشرة ومقطعة إلى مكعبات","4 فصوص ثوم مفرومة","1 كوب عدس أخضر مفرز ومغسول","5 أكواب زهيرات قرنبيط مقطعة إلى قطع بحجم لقمة","2 غصن إكليل الجبل (روزماري) طازج","2 ورقة غار","6 أكواب مرق خضار","1 كوب صلصة طماطم أو هريس طماطم من اختيارك","1 ملعقة صغيرة مسحوق البصل","1 ملعقة صغيرة مسحوق الثوم","ملح وفلفل حسب الرغبة","بقدونس أو ريحان طازج مفروم ناعمًا، للتزيين"],
["في قدر حساء كبير أو قدر ثقيل، قلّب البصل والجزر مع 1-2 ملعقة كبيرة من الماء أو المرق حتى تلين. حوالي 5-7 دقائق. ثم أضف الثوم وحرّك حتى تفوح رائحته، حوالي 30 ثانية.",
"أضف جميع المكونات المتبقية (باستثناء الزينة) إلى القدر واتركها حتى يغلي الحساء. ثم اخفض الحرارة إلى متوسطة، واطبخ الحساء والغطاء على القدر حتى ينضج العدس والقرنبيط، حوالي 15-20 دقيقة.",
"أطفئ النار وأخرج أوراق الغار وأغصان إكليل الجبل من القدر. تذوّق للتأكد من الملح والفلفل وعدّلهما عند الحاجة. ثم قدّمه."],
["استخدم مرقًا غنيًا بالنكهة جدًا! وإذا كان مرقك يفتقر إلى النكهة، فاحرص على تعديل التوابل.","إذا لم يكن لديك مرق جاهز، فيمكنك تحضيره بوصفة مكعبات المرق السهلة هذه. (أنصح بشدة بهذا المرق لنكهته الرائعة.)","استخدم 6-8 أكواب من مرق الخضار حسب الثخانة التي تفضلها. للحصول على حساء أثخن، استخدم ستة أكواب. وللحصول على حساء أخف، استخدم ثمانية. تذكّر: سيمتص الحساء مزيدًا من السائل عند تبريده.","يُحفظ المتبقي في الثلاجة لمدة تصل إلى 4 أيام، أو مجمدًا لمدة تصل إلى 3 أشهر."],
{})
